using System;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Windows.Forms;
using MyDay.Windows.Core;
namespace MyDay.Windows.UI {
 public sealed class TetrisGameWindow:Form {
  private readonly TetrisGame game=new TetrisGame(Environment.TickCount);private readonly Timer timer=new Timer{Interval=20};private readonly Stopwatch clock=Stopwatch.StartNew();private readonly TetrisCanvas canvas;private readonly Button start=Design.Button("게임 시작",true),pause=Design.Button("일시정지");private TetrisRecordStore recordStore;private int highScore;private bool roundHandled;private double lastDrop;private bool spaceDown,pauseDown;
  public TetrisGameWindow(){Text="MyDay · 테트리스";BackColor=Design.Paper;Font=Design.Font(10);StartPosition=FormStartPosition.CenterParent;ClientSize=Design.Size(820,700);MinimumSize=Design.Size(680,620);KeyPreview=true;recordStore=new TetrisRecordStore(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MyDay","Windows"));try{highScore=recordStore.Load();}catch(Exception ex){recordStore=null;MessageBox.Show(this,"저장된 테트리스 최고 점수를 읽지 못했어요. 이번 판은 계속할 수 있지만 기록은 저장되지 않습니다.\n"+ex.Message,"MyDay · 테트리스",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
   var header=new Panel{Dock=DockStyle.Top,Height=Design.P(78),BackColor=Design.Paper};var title=Design.Label("상몬 테트리스",20,true);title.Location=Design.Point(26,10);header.Controls.Add(title);var subtitle=Design.Label("블록을 맞춰 줄을 지우고 점수를 올려요.",9);subtitle.ForeColor=Design.Muted;subtitle.Location=Design.Point(28,46);header.Controls.Add(subtitle);
   var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=Design.P(62),Padding=Design.Pad(20,12,8,8),WrapContents=false,BackColor=Design.Paper};start.Size=Design.Size(124,36);pause.Size=Design.Size(108,36);var hint=Design.Label("← → 이동   ·   ↑ 회전   ·   ↓ 내리기   ·   Space 떨어뜨리기   ·   P 멈춤",9);hint.Margin=Design.Pad(14,9,0,0);footer.Controls.AddRange(new Control[]{start,pause,hint});
   canvas=new TetrisCanvas(game,()=>highScore){Dock=DockStyle.Fill};Controls.Add(canvas);Controls.Add(header);Controls.Add(footer);start.Click+=delegate{StartRound();};pause.Click+=delegate{TogglePause();};canvas.MouseDown+=delegate{canvas.Focus();};KeyDown+=OnGameKeyDown;KeyUp+=delegate(object s,KeyEventArgs e){if(e.KeyCode==Keys.Space)spaceDown=false;if(e.KeyCode==Keys.P)pauseDown=false;};KeyPress+=delegate(object s,KeyPressEventArgs e){if(" rpRP".IndexOf(e.KeyChar)>=0)e.Handled=true;};Deactivate+=delegate{if(game.State==TetrisState.Playing)PauseRound();};timer.Tick+=delegate{if(game.State==TetrisState.Playing&&clock.Elapsed.TotalSeconds-lastDrop>=DropInterval()){game.Tick();lastDrop=clock.Elapsed.TotalSeconds;UpdateControls();canvas.Invalidate();}};Shown+=delegate{lastDrop=clock.Elapsed.TotalSeconds;timer.Start();canvas.Focus();};FormClosing+=delegate{timer.Stop();};UpdateControls();
  }
  private double DropInterval(){return Math.Max(.085,.68-(game.Level-1)*.055);}
  private void OnGameKeyDown(object sender,KeyEventArgs e){bool handled=true;if(e.KeyCode==Keys.Left)game.Move(-1);else if(e.KeyCode==Keys.Right)game.Move(1);else if(e.KeyCode==Keys.Down){game.SoftDrop();lastDrop=clock.Elapsed.TotalSeconds;}else if(e.KeyCode==Keys.Up||e.KeyCode==Keys.X)game.Rotate();else if(e.KeyCode==Keys.Space){if(!spaceDown){spaceDown=true;if(game.State==TetrisState.Playing)game.HardDrop();else if(game.State==TetrisState.Paused)game.Resume();else StartRound();}}else if(e.KeyCode==Keys.P){if(!pauseDown){pauseDown=true;TogglePause();}}else if(e.KeyCode==Keys.Escape)TogglePause();else if(e.KeyCode==Keys.R)StartRound();else handled=false;if(handled){e.Handled=true;e.SuppressKeyPress=true;UpdateControls();canvas.Invalidate();}}
  private void StartRound(){game.Start();roundHandled=false;lastDrop=clock.Elapsed.TotalSeconds;UpdateControls();canvas.Focus();canvas.Invalidate();}
  private void PauseRound(){game.Pause();UpdateControls();canvas.Invalidate();}
  private void TogglePause(){if(game.State==TetrisState.Playing)game.Pause();else if(game.State==TetrisState.Paused)game.Resume();lastDrop=clock.Elapsed.TotalSeconds;UpdateControls();canvas.Focus();canvas.Invalidate();}
  private void UpdateControls(){start.Text=game.State==TetrisState.Ready?"게임 시작":game.State==TetrisState.GameOver?"다시 하기":"처음부터";pause.Text=game.State==TetrisState.Paused?"계속하기":"일시정지";pause.Enabled=game.State==TetrisState.Playing||game.State==TetrisState.Paused;if(game.State==TetrisState.GameOver&&!roundHandled){roundHandled=true;if(recordStore!=null&&game.Score>highScore)try{highScore=recordStore.SaveIfHigher(game.Score);}catch(Exception ex){recordStore=null;MessageBox.Show(this,"최고 점수를 저장하지 못했어요.\n"+ex.Message,"MyDay · 테트리스",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}}
  protected override void Dispose(bool disposing){if(disposing)timer.Dispose();base.Dispose(disposing);}
 }
 internal sealed class TetrisCanvas:Control {
  private readonly TetrisGame game;private readonly Func<int> highScore;private const int Cell=27,BoardX=190,BoardY=24;
  public TetrisCanvas(TetrisGame game,Func<int> highScore){this.game=game;this.highScore=highScore;DoubleBuffered=true;TabStop=true;SetStyle(ControlStyles.Selectable|ControlStyles.ResizeRedraw,true);AccessibleName="테트리스. 좌우 이동, 위 회전, 아래 빠르게 내리기, 스페이스 즉시 떨어뜨리기. 최고 점수가 표시됩니다.";}
  protected override bool IsInputKey(Keys keyData){Keys k=keyData&Keys.KeyCode;return k==Keys.Left||k==Keys.Right||k==Keys.Up||k==Keys.Down||base.IsInputKey(keyData);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Design.Paper);float scale=Math.Min((Width-30f)/(BoardX+TetrisGame.Columns*Cell+250),(Height-24f)/(BoardY+TetrisGame.Rows*Cell+24));if(scale<=0)return;var state=g.Save();g.TranslateTransform(Math.Max(12,(Width-(BoardX+TetrisGame.Columns*Cell+205)*scale)/2),Math.Max(12,(Height-(BoardY+TetrisGame.Rows*Cell+12)*scale)/2));g.ScaleTransform(scale,scale);DrawBoard(g);DrawInfo(g);DrawOverlay(g);g.Restore(state);}
  private void DrawBoard(Graphics g){var board=new Rectangle(BoardX-7,BoardY-7,TetrisGame.Columns*Cell+14,TetrisGame.Rows*Cell+14);using(var path=Design.Rounded(board,16))using(var b=new SolidBrush(Color.FromArgb(250,248,242)))g.FillPath(b,path);using(var pen=new Pen(Color.FromArgb(228,220,207),1))g.DrawRectangle(pen,BoardX-1,BoardY-1,TetrisGame.Columns*Cell+1,TetrisGame.Rows*Cell+1);for(int y=0;y<TetrisGame.Rows;y++)for(int x=0;x<TetrisGame.Columns;x++){int kind=game.Cell(x,y)-1;if(kind>=0)Block(g,BoardX+x*Cell,BoardY+y*Cell,kind);else{using(var pen=new Pen(Color.FromArgb(239,233,223),1))g.DrawRectangle(pen,BoardX+x*Cell,BoardY+y*Cell,Cell,Cell);}}if(game.Current!=null&&game.State!=TetrisState.GameOver)foreach(var p in game.Current.Cells){int x=game.Current.X+p.X,y=game.Current.Y+p.Y;if(y>=0)Block(g,BoardX+x*Cell,BoardY+y*Cell,game.Current.Kind);}}
  private void DrawInfo(Graphics g){using(var card=Design.Rounded(new RectangleF(10,190,154,108),14))using(var fill=new SolidBrush(Color.FromArgb(250,248,242)))g.FillPath(fill,card);DrawText(g,"최고 기록",24,207,9,Design.Muted,true);DrawText(g,highScore().ToString("N0"),24,232,20,Design.Olive,true);DrawText(g,"BEST SCORE",24,270,8,Design.Muted,false);int x=BoardX+TetrisGame.Columns*Cell+40;DrawText(g,"SCORE",x,30,10,Design.Muted,true);DrawText(g,game.Score.ToString("N0"),x,50,25,Design.Olive,true);using(var pen=new Pen(Color.FromArgb(225,215,200),1))g.DrawLine(pen,x,108,x+165,108);DrawText(g,"LEVEL",x,128,10,Design.Muted,true);DrawText(g,game.Level.ToString(),x,148,18,Design.Ink,true);DrawText(g,"LINES",x,190,10,Design.Muted,true);DrawText(g,game.Lines.ToString(),x,210,18,Design.Ink,true);DrawText(g,"NEXT",x,252,10,Design.Muted,true);using(var path=Design.Rounded(new Rectangle(x-8,274,160,116),14))using(var b=new SolidBrush(Color.FromArgb(250,248,242)))g.FillPath(b,path);foreach(var p in Preview(game.NextKind))Block(g,x+56+p.X*23,286+p.Y*23,game.NextKind);DrawText(g,"줄 1개 · 100점",x,414,10,Design.Muted,false);DrawText(g,"4줄 · 800점",x,437,10,Design.Muted,false);DrawText(g,"(레벨에 따라 가산)",x,460,9,Design.Muted,false);}
  private void DrawOverlay(Graphics g){if(game.State==TetrisState.Playing)return;var veil=new SolidBrush(Color.FromArgb(208,250,248,242));g.FillRectangle(veil,BoardX,BoardY,TetrisGame.Columns*Cell,TetrisGame.Rows*Cell);veil.Dispose();string title=game.State==TetrisState.Ready?"시작해 볼까요?":game.State==TetrisState.Paused?"잠깐 쉬는 중":"게임 종료";DrawText(g,title,BoardX+22,BoardY+220,18,Design.Olive,true);string detail=game.State==TetrisState.Ready?"게임 시작 버튼 또는 Space":game.State==TetrisState.GameOver?"최종 점수  "+game.Score.ToString("N0"):"계속하기 또는 P를 눌러요.";DrawText(g,detail,BoardX+15,BoardY+262,9,Design.Muted,false);}
  private static Point[] Preview(int kind){// The same canonical 4x4 masks used by the game model.
   switch(kind){case 0:return new[]{new Point(0,1),new Point(1,1),new Point(2,1),new Point(3,1)};case 1:return new[]{new Point(1,0),new Point(2,0),new Point(1,1),new Point(2,1)};case 2:return new[]{new Point(1,0),new Point(0,1),new Point(1,1),new Point(2,1)};case 3:return new[]{new Point(1,0),new Point(2,0),new Point(0,1),new Point(1,1)};case 4:return new[]{new Point(0,0),new Point(1,0),new Point(1,1),new Point(2,1)};case 5:return new[]{new Point(0,0),new Point(0,1),new Point(1,1),new Point(2,1)};default:return new[]{new Point(2,0),new Point(0,1),new Point(1,1),new Point(2,1)};}}
  private static void Block(Graphics g,int x,int y,int kind){var r=new Rectangle(x+2,y+2,Cell-4,Cell-4);using(var path=Design.Rounded(r,5))using(var b=new SolidBrush(TetrisGame.Colors[kind]))g.FillPath(b,path);using(var p=new Pen(Color.FromArgb(78,70,64,45),1))g.DrawRectangle(p,r);using(var p=new Pen(Color.FromArgb(90,255,255,255),2))g.DrawLine(p,x+6,y+5,x+Cell-7,y+5);}
  private static void DrawText(Graphics g,string value,int x,int y,float size,Color color,bool bold){var font=Design.Font(size,bold);using(var brush=new SolidBrush(color))g.DrawString(value,font,brush,x,y);}
 }
}
